#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
A2A Mesh — Conclusion schema with identity-pollution prevention.

Core idea:
  identity = attribution
  - Episodic memory stays node-local (first-person).
  - Conclusions enter shared_a2a_memory ONLY with an origin_peer tag.
  - Foreign conclusions are treated as quotes, never as own memories.
  - Hot path = live-query; sync = cold consolidation only.
  - Contradiction detection: two nodes publishing opposite conclusions
    from the same delta are flagged for reconciliation.

Schema:
  Conclusion = {
      id: str,
      origin_peer: str,          # who authored this conclusion
      confidence: float,         # 0.0 - 1.0
      derived_from_ids: list[str],  # episodic memory IDs (node-local)
      content: str,              # the conclusion text
      delta_id: str | None,      # which delta triggered it (for contradiction detection)
      timestamp: float,
  }

  Node-local wrapper adds:
      foreign: bool   # True if origin_peer != this node's peer_id
"""

from __future__ import annotations

import json
import os
import time
import uuid
import hashlib
import threading
from dataclasses import dataclass, field, asdict
from typing import Optional
from collections import defaultdict


# ---------------------------------------------------------------------------
# Data structures
# ---------------------------------------------------------------------------

@dataclass
class Conclusion:
    """A conclusion authored by a peer, shared across the mesh."""
    id: str
    origin_peer: str
    confidence: float
    derived_from_ids: list[str]
    content: str
    delta_id: Optional[str] = None
    timestamp: float = field(default_factory=time.time)

    def to_dict(self) -> dict:
        return asdict(self)

    @staticmethod
    def from_dict(d: dict) -> "Conclusion":
        return Conclusion(
            id=d["id"],
            origin_peer=d["origin_peer"],
            confidence=d["confidence"],
            derived_from_ids=d.get("derived_from_ids", []),
            content=d["content"],
            delta_id=d.get("delta_id"),
            timestamp=d.get("timestamp", time.time()),
        )

    def to_json(self) -> str:
        return json.dumps(self.to_dict(), sort_keys=True)

    def fingerprint(self) -> str:
        """Stable hash for dedup / contradiction detection."""
        h = hashlib.sha256()
        h.update(self.origin_peer.encode())
        h.update(self.delta_id.encode() if self.delta_id else b"none")
        h.update(self.content.encode())
        return h.hexdigest()


@dataclass
class EpisodicMemory:
    """Node-local first-person memory. NEVER shared directly."""
    id: str
    peer_id: str          # always == local node
    content: str
    timestamp: float = field(default_factory=time.time)


@dataclass
class LocalConclusion:
    """Node-local view of a Conclusion with the 'foreign' flag."""
    conclusion: Conclusion
    foreign: bool

    def to_dict(self) -> dict:
        d = self.conclusion.to_dict()
        d["foreign"] = self.foreign
        return d


# ---------------------------------------------------------------------------
# Contradiction record
# ---------------------------------------------------------------------------

@dataclass
class Contradiction:
    delta_id: str
    conclusions: list[Conclusion]
    detected_at: float = field(default_factory=time.time)

    def to_dict(self) -> dict:
        return {
            "delta_id": self.delta_id,
            "conclusions": [c.to_dict() for c in self.conclusions],
            "detected_at": self.detected_at,
        }


# ---------------------------------------------------------------------------
# Node: the local A2A Mesh agent
# ---------------------------------------------------------------------------

class A2AMeshNode:
    """
    A single node in the A2A mesh.

    - Maintains node-local episodic memories (never shared).
    - Publishes conclusions to shared_a2a_memory with origin_peer tag.
    - Marks incoming foreign conclusions with foreign=True.
    - Detects contradictions when two peers publish opposite conclusions
      from the same delta.
    - Hot path: live-query over shared memory.
    - Cold path: consolidation / sync (not delta-based).
    """

    def __init__(self, peer_id: str, shared_store_path: str = "shared_a2a_memory.json"):
        self.peer_id = peer_id
        self.shared_store_path = shared_store_path
        self._lock = threading.RLock()

        # Node-local episodic memories — first person, never shared.
        self._episodic: dict[str, EpisodicMemory] = {}

        # Node-local view of all conclusions (own + foreign), with foreign flag.
        self._local_conclusions: dict[str, LocalConclusion] = {}

        # Contradictions detected
        self._contradictions: list[Contradiction] = []

        # Index: delta_id -> list of conclusion ids
        self._delta_index: dict[str, list[str]] = defaultdict(list)

        # Load shared store if it exists
        self._load_shared_store()

    # ------------------------------------------------------------------
    # Episodic memory (node-local, first-person)
    # ------------------------------------------------------------------

    def add_episodic(self, content: str) -> str:
        """Record a first-person episodic memory. Stays local."""
        with self._lock:
            mem_id = f"ep_{uuid.uuid4().hex[:12]}"
            mem = EpisodicMemory(id=mem_id, peer_id=self.peer_id, content=content)
            self._episodic[mem_id] = mem
            return mem_id

    def get_episodic(self, mem_id: str) -> Optional[EpisodicMemory]:
        return self._episodic.get(mem_id)

    def list_episodic(self) -> list[EpisodicMemory]:
        return list(self._episodic.values())

    # ------------------------------------------------------------------
    # Conclusion publishing
    # ------------------------------------------------------------------

    def publish_conclusion(
        self,
        content: str,
        confidence: float,
        derived_from_ids: list[str],
        delta_id: Optional[str] = None,
    ) -> Conclusion:
        """
        Publish a conclusion to shared_a2a_memory.

        The conclusion is tagged with origin_peer = self.peer_id.
        Locally it is stored with foreign=False.
        """
        if not (0.0 <= confidence <= 1.0):
            raise ValueError("confidence must be between 0.0 and 1.0")

        # Verify derived_from_ids are local episodic memories
        for mid in derived_from_ids:
            if mid not in self._episodic:
                raise ValueError(
                    f"derived_from_id {mid} is not a local episodic memory; "
                    "conclusions can only be derived from own first-person memories"
                )

        with self._lock:
            concl_id = f"cl_{uuid.uuid4().hex[:12]}"
            concl = Conclusion(
                id=concl_id,
                origin_peer=self.peer_id,
                confidence=confidence,
                derived_from_ids=list(derived_from_ids),
                content=content,
                delta_id=delta_id,
            )

            # Store locally as own (foreign=False)
            self._local_conclusions[concl_id] = LocalConclusion(
                conclusion=concl, foreign=False
            )

            if delta_id:
                self._delta_index[delta_id].append(concl_id)

            # Persist to shared store
            self._save_shared_store()

            # Check for contradictions
            self._check_contradictions(delta_id)

            return concl

    # ------------------------------------------------------------------
    # Receiving foreign conclusions
    # ------------------------------------------------------------------

    def receive_conclusion(self, concl: Conclusion) -> LocalConclusion:
        """
        Receive a conclusion from another peer.

        It is ALWAYS marked foreign=True if origin_peer != self.peer_id.
        Foreign conclusions are treated as quotes, never as own memories.
        """
        with self._lock:
            is_foreign = concl.origin_peer != self.peer_id
            local = LocalConclusion(conclusion=concl, foreign=is_foreign)
            self._local_conclusions[concl.id] = local

            if concl.delta_id:
                self._delta_index[concl.delta_id].append(concl.id)

            self._save_shared_store()
            self._check_contradictions(concl.delta_id)
            return local

    # ------------------------------------------------------------------
    # Querying (hot path = live-query)
    # ------------------------------------------------------------------

    def live_query(self, query: str = "", own_only: bool = False) -> list[LocalConclusion]:
        """
        Hot-path live query over local conclusions.

        If own_only=True, returns only non-foreign (own) conclusions.
        Otherwise returns all, with foreign flag visible.
        """
        with self._lock:
            results = []
            for lc in self._local_conclusions.values():
                if own_only and lc.foreign:
                    continue
                if query and query.lower() not in lc.conclusion.content.lower():
                    continue
                results.append(lc)
            results.sort(key=lambda lc: lc.conclusion.timestamp, reverse=True)
            return results

    def get_as_quote(self, concl_id: str) -> Optional[str]:
        """
        Return a foreign conclusion as a quoted attribution string.

        This enforces: foreign conclusions are quotes, not own memories.
        """
        lc = self._local_conclusions.get(concl_id)
        if lc is None:
            return None
        if not lc.foreign:
            # Own conclusion — return as-is (first person)
            return lc.conclusion.content
        # Foreign — wrap as quote with attribution
        return f'[quote from {lc.conclusion.origin_peer}] "{lc.conclusion.content}"'

    # ------------------------------------------------------------------
    # Contradiction detection
    # ------------------------------------------------------------------

    def _check_contradictions(self, delta_id: Optional[str]) -> None:
        """
        If two nodes publish conclusions from the same delta_id,
        check for contradictory content.

        Simple heuristic: if two conclusions from different peers share
        a delta_id and one contains a negation marker the other doesn't,
        or they use opposing sentiment words, flag as contradiction.
        """
        if not delta_id:
            return

        concl_ids = self._delta_index.get(delta_id, [])
        if len(concl_ids) < 2:
            return

        # Group by peer
        by_peer: dict[str, Conclusion] = {}
        for cid in concl_ids:
            lc = self._local_conclusions.get(cid)
            if lc:
                by_peer[lc.conclusion.origin_peer] = lc.conclusion

        if len(by_peer) < 2:
            return

        # Check for contradictions among different peers
        peers = list(by_peer.values())
        contradiction_found = False
        negation_markers = ["not", "no", "never", "false", "incorrect", "wrong", "contra", "deny", "reject"]

        for i in range(len(peers)):
            for j in range(i + 1, len(peers)):
                c1, c2 = peers[i], peers[j]
                if c1.origin_peer == c2.origin_peer:
                    continue
                # Heuristic: check if one negates the other
                words1 = set(c1.content.lower().split())
                words2 = set(c2.content.lower().split())
                neg1 = words1 & set(negation_markers)
                neg2 = words2 & set(negation_markers)
                # If one has negation and the other doesn't, and they share
                # significant content overlap
                overlap = words1 & words2 - set(negation_markers)
                if (neg1 and not neg2) or (neg2 and not neg1):
                    if len(overlap) >= 2:
                        contradiction_found = True
                # Also: if confidence is high but content differs significantly
                if c1.confidence > 0.7 and c2.confidence > 0.7:
                    if c1.content.strip().lower() != c2.content.strip().lower():
                        # Different high-confidence conclusions from same delta
                        contradiction_found = True

        if contradiction_found:
            # Check if we already recorded this
            existing_delta_ids = {c.delta_id for c in self._contradictions}
            if delta_id not in existing_delta_ids:
                self._contradictions.append(
                    Contradiction(
                        delta_id=delta_id,
                        conclusions=peers,
                    )
                )

    def get_contradictions(self) -> list[Contradiction]:
        return list(self._contradictions)

    # ------------------------------------------------------------------
    # Cold consolidation / sync
    # ------------------------------------------------------------------

    def consolidate(self) -> dict:
        """
        Cold-path consolidation. Summarizes the state for sync.

        This is NOT a delta sync — it's a cold snapshot for archival
        or reconciliation. The hot path is live-query.
        """
        with self._lock:
            own = [lc for lc in self._local_conclusions.values() if not lc.foreign]
            foreign = [lc for lc in self._local_conclusions.values() if lc.foreign]
            return {
                "peer_id": self.peer_id,
                "episodic_count": len(self._episodic),
                "own_conclusions": len(own),
                "foreign_conclusions": len(foreign),
                "contradictions": len(self._contradictions),
                "consolidated_at": time.time(),
            }

    # ------------------------------------------------------------------
    # Shared store persistence
    # ------------------------------------------------------------------

    def _save_shared_store(self) -> None:
        """Persist all conclusions to the shared store file."""
        data = {
            "conclusions": [
                lc.conclusion.to_dict()
                for lc in self._local_conclusions.values()
            ],
        }
        tmp = self.shared_store_path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, ensure_ascii=False)
        os.replace(tmp, self.shared_store_path)

    def _load_shared_store(self) -> None:
        """Load conclusions from shared store if it exists."""
        if not os.path.exists(self.shared_store_path):
            return
        try:
            with open(self.shared_store_path, "r", encoding="utf-8") as f:
                data = json.load(f)
            for cd in data.get("conclusions", []):
                concl = Conclusion.from_dict(cd)
                is_foreign = concl.origin_peer != self.peer_id
                self._local_conclusions[concl.id] = LocalConclusion(
                    conclusion=concl, foreign=is_foreign
                )
                if concl.delta_id:
                    self._delta_index[concl.delta_id].append(concl.id)
        except (json.JSONDecodeError, KeyError):
            pass

    # ------------------------------------------------------------------
    # Identity-pollution guard
    # ------------------------------------------------------------------

    def assert_no_identity_pollution(self) -> bool:
        """
        Verify that no foreign conclusion has been misattributed as own.

        Returns True if clean, raises AssertionError if polluted.
        """
        with self._lock:
            for lc in self._local_conclusions.values():
                if lc.foreign and lc.conclusion.origin_peer == self.peer_id:
                    raise AssertionError(
                        f"IDENTITY POLLUTION: conclusion {lc.conclusion.id} "
                        f"has foreign=True but origin_peer == self.peer_id"
                    )
                if not lc.foreign and lc.conclusion.origin_peer != self.peer_id:
                    raise AssertionError(
                        f"IDENTITY POLLUTION: conclusion {lc.conclusion.id} "
                        f"has foreign=False but origin_peer != self.peer_id"
                    )
            return True


# ---------------------------------------------------------------------------
# Demo / self-test
# ---------------------------------------------------------------------------

def _demo():
    print("=" * 70)
    print("A2A Mesh — Conclusion schema with identity-pollution prevention")
    print("Generated by runa via A2A Mesh delegation")
    print("=" * 70)

    # Create two nodes sharing a store file
    store = "shared_a2a_memory_demo.json"
    # Clean up any previous demo store
    if os.path.exists(store):
        os.remove(store)

    alice = A2AMeshNode(peer_id="alice", shared_store_path=store)
    bob = A2AMeshNode(peer_id="bob", shared_store_path=store)

    # --- Alice records episodic memories (node-local, first person) ---
    ep1 = alice.add_episodic("I observed the service returning 500 errors at 3am.")
    ep2 = alice.add_episodic("I saw the database connection pool exhausted.")
    print(f"\n[alice] Episodic memories (local only): {len(alice.list_episodic())}")

    # --- Alice publishes a conclusion derived from her episodic memories ---
    concl_a = alice.publish_conclusion(
        content="The 3am outage was caused by database connection pool exhaustion.",
        confidence=0.85,
        derived_from_ids=[ep1, ep2],
        delta_id="delta_001",
    )
    print(f"[alice] Published conclusion: {concl_a.id}")
    print(f"         origin_peer={concl_a.origin_peer}, confidence={concl_a.confidence}")

    # --- Bob records his own episodic memories ---
    ep3 = bob.add_episodic("I checked the logs and the pool was fine at 3am.")
    ep4 = bob.add_episodic("I saw a deploy happened at 2:55am.")

    # --- Bob publishes a contradictory conclusion from the same delta ---
    concl_b = bob.publish_conclusion(
        content="The 3am outage was NOT caused by pool exhaustion; a deploy broke it.",
        confidence=0.80,
        derived_from_ids=[ep3, ep4],
        delta_id="delta_001",
    )
    print(f"[bob]   Published conclusion: {concl_b.id}")
    print(f"         origin_peer={concl_b.origin_peer}, confidence={concl_b.confidence}")

    # --- Bob receives Alice's conclusion (via shared store reload) ---
    bob2 = A2AMeshNode(peer_id="bob", shared_store_path=store)
    # Find alice's conclusion in bob's local view
    alice_concl_for_bob = None
    for lc in bob2._local_conclusions.values():
        if lc.conclusion.origin_peer == "alice":
            alice_concl_for_bob = lc
            break

    if alice_concl_for_bob:
        print(f"\n[bob]   Received alice's conclusion:")
        print(f"         foreign={alice_concl_for_bob.foreign}  "
              f"(origin_peer={alice_concl_for_bob.conclusion.origin_peer})")
        quote = bob2.get_as_quote(alice_concl_for_bob.conclusion.id)
        print(f"         As quote: {quote}")

    # --- Alice receives Bob's conclusion ---
    alice2 = A2AMeshNode(peer_id="alice", shared_store_path=store)
    bob_concl_for_alice = None
    for lc in alice2._local_conclusions.values():
        if lc.conclusion.origin_peer == "bob":
            bob_concl_for_alice = lc
            break

    if bob_concl_for_alice:
        print(f"\n[alice] Received bob's conclusion:")
        print(f"         foreign={bob_concl_for_alice.foreign}  "
              f"(origin_peer={bob_concl_for_alice.conclusion.origin_peer})")
        quote = alice2.get_as_quote(bob_concl_for_alice.conclusion.id)
        print(f"         As quote: {quote}")

    # --- Contradiction detection ---
    print(f"\n[alice] Contradictions detected: {len(alice2.get_contradictions())}")
    for c in alice2.get_contradictions():
        print(f"         delta_id={c.delta_id}")
        for concl in c.conclusions:
            print(f"           - {concl.origin_peer}: {concl.content}")

    # --- Live query (hot path) ---
    print(f"\n[alice] Live query (own only):")
    for lc in alice2.live_query(own_only=True):
        print(f"         [own]  conf={lc.conclusion.confidence:.2f}  {lc.conclusion.content}")

    print(f"\n[alice] Live query (all, with foreign flag):")
    for lc in alice2.live_query():
        tag = "foreign" if lc.foreign else "own"
        print(f"         [{tag}] origin={lc.conclusion.origin_peer}  "
              f"conf={lc.conclusion.confidence:.2f}  {lc.conclusion.content}")

    # --- Identity pollution guard ---
    print(f"\n[alice] Identity pollution check: ", end="")
    try:
        alice2.assert_no_identity_pollution()
        print("CLEAN ✓")
    except AssertionError as e:
        print(f"FAILED ✗ — {e}")

    # --- Cold consolidation ---
    print(f"\n[alice] Cold consolidation snapshot:")
    snapshot = alice2.consolidate()
    for k, v in snapshot.items():
        print(f"         {k}: {v}")

    # --- Demonstrate that foreign conclusions cannot be re-published as own ---
    print(f"\n[alice] Attempting to re-publish bob's conclusion as own (should fail):")
    try:
        # Alice tries to derive a conclusion from Bob's conclusion ID
        # But derived_from_ids must be local episodic memories
        alice2.publish_conclusion(
            content="Stolen conclusion",
            confidence=0.9,
            derived_from_ids=[bob_concl_for_alice.conclusion.id],  # not an episodic memory
        )
        print("         ERROR: should have been rejected!")
    except ValueError as e:
        print(f"         Correctly rejected: {e}")

    # Cleanup
    if os.path.exists(store):
        os.remove(store)

    print(f"\n{'=' * 70}")
    print("Demo complete. Identity pollution prevention verified.")
    print(f"{'=' * 70}")


if __name__ == "__main__":
    _demo()